// Trained four-head MBTI evidence classifier.
//
// Generated by `scripts/train-mbti-linear.py`; do not hand-edit the JSON artifact.
// Each axis is an independent 3-class head over shared boundary-marked Unicode
// character 1-4 grams: [insufficient, left pole, right pole]. The output keeps the
// existing PersonalityEvidence wire shape, so the Python accumulation/aggregation
// gates (100 messages / 30 evidence / 0.2 margin) are unchanged.
import modelData from "./mbti-linear-model.json";
import type { PersonalityEvidence } from "./personality";

interface MbtiLinearModel {
  version: string;
  algorithm: string;
  features: string;
  corpusSha256: string;
  axes: string[];
  axisLabels: Record<string, string[]>;
  axisOffsets: Record<string, number>;
  sizes: number[];
  prefix: string;
  suffix: string;
  temperatures: number[];
  l2: number;
  epochs: number;
  pruneThreshold: number;
  bias: number[];
  weights: Record<string, number[]>;
  vocabSize: number;
  exportedGrams: number;
}

const model = modelData as MbtiLinearModel;

export const MBTI_LINEAR_VERSION = model.version;

/** Unique boundary-marked character n-grams. Must mirror the Python trainer. */
export function mbtiTextGrams(text: string): string[] {
  const compact = [model.prefix, ...Array.from(text).filter((char) => !/\s/u.test(char)),
    model.suffix];
  const grams = new Set<string>();
  for (const size of model.sizes) {
    for (let index = 0; index + size <= compact.length; index++) {
      grams.add(compact.slice(index, index + size).join(""));
    }
  }
  return [...grams];
}

/** Normalized [insufficient, left, right] probabilities for every axis. */
export function mbtiAxisProbabilities(text: string): Record<string, number[]> {
  const scores = [...model.bias];
  for (const gram of mbtiTextGrams(text)) {
    const values = model.weights[gram];
    if (!values) continue;
    for (let index = 0; index < scores.length; index++) {
      scores[index] = scores[index]! + (values[index] ?? 0);
    }
  }
  const result: Record<string, number[]> = {};
  model.axes.forEach((axis, axisIndex) => {
    const offset = model.axisOffsets[axis]!;
    const temperature = model.temperatures[axisIndex]!;
    const slice = scores.slice(offset, offset + 3).map((score) => score / temperature);
    const maximum = Math.max(...slice);
    const exponents = slice.map((score) => Math.exp(score - maximum));
    const total = exponents.reduce((sum, value) => sum + value, 0);
    result[axis] = exponents.map((value) => total > 0 ? value / total : 1 / 3);
  });
  return result;
}

function toEvidence(probabilities: Record<string, number[]>): PersonalityEvidence {
  const read = (axis: string, left: string, right: string) => {
    const values = probabilities[axis] ?? [1, 0, 0];
    return { [left]: values[1] ?? 0, [right]: values[2] ?? 0,
      insufficient: values[0] ?? 0 } as Record<string, number>;
  };
  const EI = read("EI", "E", "I") as unknown as PersonalityEvidence["EI"];
  const SN = read("SN", "S", "N") as unknown as PersonalityEvidence["SN"];
  const TF = read("TF", "T", "F") as unknown as PersonalityEvidence["TF"];
  const JP = read("JP", "J", "P") as unknown as PersonalityEvidence["JP"];
  return { EI, SN, TF, JP };
}

function supported(evidence: PersonalityEvidence): boolean {
  const axes = [evidence.EI, evidence.SN, evidence.TF, evidence.JP];
  return axes.some((axis) => {
    const values = axis as unknown as Record<string, number>;
    const poles = Object.entries(values).filter(([key]) => key !== "insufficient");
    return poles.some(([, value]) => value > values.insufficient!);
  });
}

/** One message's MBTI evidence. Mirrors `personalityEvidenceFromAnswers`' abstain gate. */
export function mbtiEvidenceForText(text: string): PersonalityEvidence | null {
  const evidence = toEvidence(mbtiAxisProbabilities(text));
  return supported(evidence) ? evidence : null;
}

/**
 * A batch of TARGET messages: average the per-message probabilities, then apply the
 * same abstain gate. Used by the API portrait path, which judges a whole window.
 */
export function mbtiEvidenceForTexts(texts: string[]): PersonalityEvidence | null {
  if (!texts.length) return null;
  const summed: Record<string, number[]> = {};
  for (const text of texts) {
    for (const [axis, values] of Object.entries(mbtiAxisProbabilities(text))) {
      const target = summed[axis] ?? [0, 0, 0];
      values.forEach((value, index) => { target[index] = (target[index] ?? 0) + value; });
      summed[axis] = target;
    }
  }
  for (const values of Object.values(summed)) {
    const total = values.reduce((sum, value) => sum + value, 0);
    if (total > 0) for (let index = 0; index < values.length; index++)
      values[index] = values[index]! / total;
  }
  const evidence = toEvidence(summed);
  return supported(evidence) ? evidence : null;
}
